pub fn errorMsg(mut txt: Tpl::Text, a_errMessage: &ArcStr) -> Result<Tpl::Text> {
    let mut out_txt;
    Tpl::addTemplateError(a_errMessage.clone())?;
    out_txt = Tpl::writeStr(txt, a_errMessage.clone())?;
    Ok(out_txt)
}

fn fun_94(mut in_txt: Tpl::Text, in_a_con: &metamodelica::Ref<DAE::Constraint>) -> Result<Tpl::Text> {
    ::match_deref::match_deref! { match in_a_con {
        Deref @ DAE::Constraint::CONSTRAINT_DT { constraint: i_c, localCon: true, .. } => {
            let mut txt = in_txt;
            txt = dumpExp(txt, i_c, &literal!("\""))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!(" (local)") }))?;
            Ok(txt)
        }
        Deref @ DAE::Constraint::CONSTRAINT_DT { constraint: i_c, localCon: false, .. } => {
            let mut txt = in_txt;
            txt = dumpExp(txt, i_c, &literal!("\""))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!(" (global)") }))?;
            Ok(txt)
        }
        _ => {
            let mut txt = in_txt;
            Ok(txt)
        }
        _ => Err("fun_94: no case matched"),
    } }
}

fn lm_95(mut txt: Tpl::Text, items: &metamodelica::List<metamodelica::Ref<DAE::Constraint>>) -> Result<Tpl::Text> {
    for lstElt_95 in items {
        ::match_deref::match_deref! { match lstElt_95 {
            i_con => {
                txt = fun_94(txt, i_con)?;
                txt = Tpl::nextIter(txt)?;
            }
            _ => return Err("lm_95: no case matched"),
        } }
    }
    Ok(txt)
}

pub fn dumpConstraints(
    mut txt: Tpl::Text,
    a_cons: &metamodelica::List<metamodelica::Ref<DAE::Constraint>>,
) -> Result<Tpl::Text> {
    let mut out_txt;
    out_txt = Tpl::pushIter(
        txt,
        metamodelica::Ref::new(Tpl::IterOptions {
            startIndex0: 0,
            empty: None,
            separator: Some(metamodelica::Ref::new(Tpl::StringToken::ST_STRING {
                value: literal!(", "),
            })),
            alignNum: 0,
            alignOfset: 0,
            alignSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE),
            wrapWidth: 0,
            wrapSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE),
        }),
    )?;
    out_txt = lm_95(out_txt, a_cons)?;
    out_txt = Tpl::popIter(out_txt)?;
    Ok(out_txt)
}
